import assert from 'node:assert/strict';
import { globalRegistry } from './providers/registry.ts';
import { handleMultiAgentChatRequest } from './handlers/multiAgentChat.ts';

const calls: any[] = [];
const provider: any = { id: 'repro', name: 'repro', type: 'openai', supportsImages: () => false, async *executeChat(request: any) {
  calls.push(request);
  if (request.message === '@parent start') yield { type: 'tool_use', toolName: 'delegate_task', toolInput: { agent_id: 'child', instructions: 'do work' }, toolUseId: 'call-1' };
  else if (request.message === 'do work') yield { type: 'text', content: 'child result' };
  else yield { type: 'text', content: 'finished' };
  yield { type: 'done' };
} };
globalRegistry.registerProvider(provider);
for (const id of ['parent', 'child']) globalRegistry.registerAgent({ id, name: id, description: id, provider: 'repro' });
const context: any = { req: { json: async () => ({ message: '@parent start', requestId: 'repro' }) }, var: { config: { debugMode: false } } };
const response = await handleMultiAgentChatRequest(context, new Map());
const chunks = (await response.text()).trim().split('\n').map(JSON.parse);
assert(calls.some(c => c.message === 'do work'), 'delegated agent was not run');
const feedback = calls.find(c => { try { return JSON.parse(c.message).type === 'tool_result'; } catch { return false; } });
assert(feedback, 'delegator did not receive a tool result');
assert.equal(JSON.parse(feedback.message).content, 'child result');
assert.equal(JSON.parse(feedback.message).tool_use_id, 'call-1');
assert(chunks.some(c => c.data?.type === 'tool_use' && c.data.id === 'call-1'));
console.log('Delegation reproduction passed');
